10	/**
11	 * Step of {@code POST /api/owners}: validates the optional {@code postcode} WHEN PRESENT. A
12	 * supplied postcode must be four digits and, for a city with a known region (derived through
13	 * {@link Locality}: Sydney&rarr;NSW, Melbourne&rarr;VIC, Brisbane&rarr;QLD), fall inside that
14	 * region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
15	 * region accepts any 4-digit postcode. An absent postcode is left untouched, so the request
16	 * contract stays backward-compatible; anything invalid is rejected 400 via
17	 * {@link InvalidPostcodeException}.
18	 */
19	public class RequirePostcode {
20	
21	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
22	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
23	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
24	
25	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
26	        String postcode = request.getPostcode();
27	        if (postcode == null || postcode.isBlank()) {
28	            return; // optional when absent
29	        }
30	        if (!postcode.matches("[0-9]{4}")) {
31	            throw new InvalidPostcodeException(postcode);
32	        }
33	        int[] range = REGION_POSTCODES.get(Locality.of(request.getCity()));
34	        if (range != null) {
35	            int value = Integer.parseInt(postcode);
36	            if (value < range[0] || value > range[1]) {
37	                throw new InvalidPostcodeException(postcode);
38	            }
39	        }
40	    }
